command:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
$taskBase=Join-Path (Get-Location) 'openspec/changes/fix-accepted-policy-preprocessing/evidence/blocker-implementation-20261026-01'
$taskNames=@('B4-desktop-base-tool-returns.original.json','B4-desktop-base-graph.derived.json','B4-desktop-base-graph-checkpoint.md','B4-desktop-base-retention.outer-tools.original.json')
$taskArchive=Join-Path $taskBase 'B4-desktop-base-originals.zip'
$taskManifestPath=Join-Path $taskBase 'B4-desktop-base-originals.manifest.json'
if((Test-Path -LiteralPath $taskArchive) -or (Test-Path -LiteralPath $taskManifestPath)){throw 'metadata archive namespace consumed'}
$taskRows=@();$taskInputs=@();$taskTotal=0
foreach($taskName in $taskNames){$taskInfo=Get-Item -LiteralPath (Join-Path $taskBase $taskName);$taskTotal+=$taskInfo.Length;if($taskTotal -gt 1048576){throw 'aggregate input cap before read'};$taskRaw=[IO.File]::ReadAllBytes($taskInfo.FullName);if($taskRaw.Length -ne $taskInfo.Length){throw 'input extent changed'};$taskSha=[Security.Cryptography.SHA256]::Create();try{$taskHash=[BitConverter]::ToString($taskSha.ComputeHash($taskRaw)).Replace('-','').ToLowerInvariant()}finally{$taskSha.Dispose()};$taskRows+=@{member=$taskName;size_bytes=$taskRaw.Length;sha256=$taskHash};$taskInputs+=,@($taskName,$taskRaw)}
if($taskTotal+65536*($taskNames.Count+1) -gt 2097152){throw 'stored ZIP preflight cap'}
$taskMemory=[IO.MemoryStream]::new()
try{$taskZip=[IO.Compression.ZipArchive]::new($taskMemory,[IO.Compression.ZipArchiveMode]::Create,$true);try{foreach($taskInput in $taskInputs){$taskEntry=$taskZip.CreateEntry($taskInput[0],[IO.Compression.CompressionLevel]::NoCompression);$taskEntryStream=$taskEntry.Open();try{$taskEntryStream.Write($taskInput[1],0,$taskInput[1].Length)}finally{$taskEntryStream.Dispose()}}}finally{$taskZip.Dispose()};if($taskMemory.Length -gt 2097152){throw 'complete ZIP too large before file open'};$taskArchiveRaw=$taskMemory.ToArray()}finally{$taskMemory.Dispose()}
$taskSha=[Security.Cryptography.SHA256]::Create();try{$taskArchiveHash=[BitConverter]::ToString($taskSha.ComputeHash($taskArchiveRaw)).Replace('-','').ToLowerInvariant()}finally{$taskSha.Dispose()}
$taskManifest=[Text.Encoding]::UTF8.GetBytes((@{schema_version=1;archive='B4-desktop-base-originals.zip';size_bytes=$taskArchiveRaw.Length;sha256=$taskArchiveHash;members=$taskRows;original_files_preserved=$true;zip_preflight_in_memory=$true}|ConvertTo-Json -Depth 6 -Compress)+"`n")
if($taskManifest.Length -gt 16384 -or $taskTotal+$taskManifest.Length -gt 1048576 -or $taskArchiveRaw.Length+$taskManifest.Length -gt 2097152){throw 'aggregate metadata forms cap'}
foreach($taskPair in @(@($taskArchive,$taskArchiveRaw),@($taskManifestPath,$taskManifest))){$taskStream=[IO.File]::Open($taskPair[0],'CreateNew','Write','Read');try{$taskStream.Write($taskPair[1],0,$taskPair[1].Length);$taskStream.Flush($true)}finally{$taskStream.Dispose()}}
@{archive='B4-desktop-base-originals.zip';size_bytes=$taskArchiveRaw.Length;sha256=$taskArchiveHash;member_count=$taskRows.Count;original_aggregate_bytes=$taskTotal}|ConvertTo-Json -Compress
